-- Synthetic evidence fixtures test gate logic ONLY. They are not genuine malware scans.
create function public.test_assert(ok boolean,label text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'FAIL %',label; end if; raise notice 'PASS %',label; end$$;
create function public.test_reject(statement text,label text) returns void language plpgsql as $$begin begin execute statement; exception when others then raise notice 'PASS %',label;return;end;raise exception 'FAIL %',label;end$$;
select public.test_assert((select not security_required and security_status='legacy_unverified' and upload_status='ready' and approval_status='pending' from public.collaboration_assets where storage_path='legacy.png'),'legacy row and artistic approval preserved');
select public.test_assert(not has_function_privilege('authenticated','public.claim_asset_for_scan(uuid,uuid,boolean)','execute'),'artist cannot claim asset scan');
select public.test_assert(not has_function_privilege('authenticated','public.claim_attachment_for_manual_scan(uuid,uuid,integer)','execute'),'artist cannot bypass retry cap');
select public.test_assert(not has_table_privilege('authenticated','public.collaboration_assets','update'),'artist cannot forge asset evidence');
select public.test_assert(not has_table_privilege('authenticated','public.collaboration_feedback_attachments','update'),'artist cannot forge attachment evidence');
select public.test_assert(not public.valid_portal_scan_evidence('{}','abc',10,gen_random_uuid()),'empty evidence rejected');
insert into public.collaboration_assets(id,collaboration_id,asset_type,storage_bucket,storage_path,display_label,mime_type,byte_size,uploaded_by) values('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000100','audio_full','collaboration-audio','new.mp3','Synthetic new asset','audio/mpeg',10,'00000000-0000-4000-8000-000000000001');
select public.test_assert((select security_required and security_status='pending' from public.collaboration_assets where storage_path='new.mp3'),'new asset defaults require security');
select public.test_reject($q$update public.collaboration_assets set upload_status='ready' where storage_path='new.mp3'$q$,'existence/size alone cannot release');
select public.test_reject($q$update public.collaboration_assets set security_required=false where storage_path='new.mp3'$q$,'security downgrade denied');
select public.claim_asset_for_scan('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000500',false);
select public.test_assert((select count(*)=0 from public.claim_asset_for_scan('00000000-0000-4000-8000-000000000102',gen_random_uuid(),false)),'duplicate active asset claim denied');
update public.collaboration_assets set scan_lease_expires_at=now()-interval '1 minute' where storage_path='new.mp3';
select public.test_assert((select count(*)=1 from public.claim_asset_for_scan('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000503',true)),'expired asset lease is recoverable by explicit administrator retry');
with late as(update public.collaboration_assets set security_status='clean' where storage_path='new.mp3' and scan_request_id='00000000-0000-4000-8000-000000000500' returning id) select public.test_assert((select count(*)=0 from late),'late asset result cannot overwrite reclaimed attempt');
update public.collaboration_assets set file_sha256=repeat('a',64),security_status='clean',scan_lease_expires_at=null,scan_evidence=jsonb_build_object('verdict','clean','provider','cloudmersive','complete',true,'withinLimits',true,'fileSha256',repeat('a',64),'fileSize',10,'attemptId',scan_request_id,'policyVersion','signal-portal-k16h2-v1','startedAt',now(),'completedAt',now()) where storage_path='new.mp3';
select public.test_reject($q$update public.collaboration_assets set upload_status='ready' where storage_path='new.mp3'$q$,'scan without administrator release approval denied');
update public.collaboration_assets set security_review_status='approved',security_reviewed_by='00000000-0000-4000-8000-000000000001',security_reviewed_at=now(),upload_status='ready' where storage_path='new.mp3';
select public.test_assert((select upload_status='ready' from public.collaboration_assets where storage_path='new.mp3'),'matching evidence plus separate review permits release');
select public.test_reject($q$update public.collaboration_assets set storage_path='replacement.mp3' where storage_path='new.mp3'$q$,'released object path immutable');
select public.test_reject($q$update public.collaboration_assets set file_sha256=repeat('b',64) where storage_path='new.mp3'$q$,'checksum substitution rejected');
select public.test_reject($q$update public.collaboration_assets set scan_evidence=jsonb_set(scan_evidence,'{complete}','false') where storage_path='new.mp3'$q$,'partial scan cannot remain available');
select public.test_reject($q$update public.collaboration_assets set scan_evidence=jsonb_set(scan_evidence,'{attemptId}','"00000000-0000-4000-8000-000000000999"') where storage_path='new.mp3'$q$,'stale evidence cannot replace current release');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
set role authenticated;
select public.test_assert((select count(*)=2 from public.collaboration_assets),'authorized artist sees own ready assets');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
set role authenticated;
select public.test_assert((select count(*)=0 from public.collaboration_assets),'unassigned artist sees zero assets');
reset role;
insert into public.collaboration_feedback(id,collaboration_id,author_id,kind,body) values('00000000-0000-4000-8000-000000000300','00000000-0000-4000-8000-000000000100','00000000-0000-4000-8000-000000000002','general','Synthetic retry fixture');
insert into public.collaboration_feedback_attachments(id,feedback_id,collaboration_id,storage_bucket,storage_path,original_filename,mime_type,byte_size,uploaded_by,status,security_status,scan_attempt_count) values('00000000-0000-4000-8000-000000000400','00000000-0000-4000-8000-000000000300','00000000-0000-4000-8000-000000000100','collaboration-attachments-quarantine','fixture.txt','fixture.txt','text/plain',10,'00000000-0000-4000-8000-000000000002','awaiting_scan','error',2);
select public.claim_attachment_for_scan('00000000-0000-4000-8000-000000000400','00000000-0000-4000-8000-000000000501',180);
select public.test_assert((select count(*)=0 from public.claim_attachment_for_scan('00000000-0000-4000-8000-000000000400',gen_random_uuid(),180)),'duplicate attachment claim denied');
update public.collaboration_feedback_attachments set security_status='error',scan_request_id=null where id='00000000-0000-4000-8000-000000000400';
select public.test_assert((select count(*)=0 from public.claim_attachment_for_scan('00000000-0000-4000-8000-000000000400',gen_random_uuid(),180)),'automatic cap atomic at three attempts');
select public.test_assert((select count(*)=1 from public.claim_attachment_for_manual_scan('00000000-0000-4000-8000-000000000400','00000000-0000-4000-8000-000000000502',180)),'explicit manual retry exception preserved');
select public.test_assert((select scan_attempt_count=4 from public.collaboration_feedback_attachments where id='00000000-0000-4000-8000-000000000400'),'manual retry count remains accurate');
with late as(update public.collaboration_feedback_attachments set security_status='clean' where id='00000000-0000-4000-8000-000000000400' and scan_request_id='00000000-0000-4000-8000-000000000501' returning id) select public.test_assert((select count(*)=0 from late),'late scan response cannot overwrite newer attempt');
select public.test_reject($q$update public.collaboration_feedback_attachments set security_status='clean',review_status='approved',status='available' where id='00000000-0000-4000-8000-000000000400'$q$,'manual approval without exact-byte scan evidence denied');
